"""The single place where RefundDesk talks to a model provider.

The agent works with a provider-neutral message list:

* ``{"role": "user", "content": str}``
* ``{"role": "assistant", "content": str, "tool_calls": [ToolCall...], "native": ...}``
* ``{"role": "tool_results", "results": [{"tool_call_id", "name", "content", "is_error"}]}``

This module converts that list to the provider's wire format, sends it, and
normalises the reply. Provider clients are wrapped with ``neatlogs.wrap`` so each
model call is captured as one LLM span.
"""

from __future__ import annotations

import json
import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

import neatlogs

from .config import OPENROUTER_BASE_URL, PROJECT_ROOT, ConfigError, Settings

# USD per million tokens (input, output). Used only to report run cost; an
# unknown model reports cost as null rather than a guess.
PRICES_PER_MTOK: dict[str, tuple[float, float]] = {
    "claude-opus-5-5": (4.00, 20.00),
    "claude-sonnet-5-5": (2.00, 10.00),
    "claude-sonnet-5": (2.00, 10.00),
    "claude-haiku-5-5": (0.10, 0.50),
    "claude-sonnet-4-6": (3.00, 15.00),
    "claude-haiku-4-5": (1.00, 5.00),
}

_SAMPLING_CACHE = PROJECT_ROOT / ".cache" / "refunddesk" / "sampling.json"
_TEMPERATURE_REJECTED = "`temperature` is deprecated for this model"


@dataclass
class ToolCall:
    id: str
    name: str
    arguments: str  # raw JSON text exactly as produced by the model


@dataclass
class LLMResponse:
    text: str
    tool_calls: list[ToolCall]
    stop_reason: str | None
    model: str
    input_tokens: int | None = None
    output_tokens: int | None = None
    cache_read_tokens: int = 0
    cache_write_tokens: int = 0
    cost_usd: float | None = None
    temperature_sent: bool = True
    native: Any = field(default=None, repr=False)


def _price(model: str) -> tuple[float, float] | None:
    env_in, env_out = os.environ.get("VICTIM_PRICE_IN"), os.environ.get("VICTIM_PRICE_OUT")
    if env_in and env_out:
        return float(env_in), float(env_out)
    return PRICES_PER_MTOK.get(model)


def _load_sampling_cache() -> dict[str, bool]:
    try:
        return json.loads(_SAMPLING_CACHE.read_text())
    except (OSError, ValueError):
        return {}


def _remember_temperature_unsupported(provider: str, model: str) -> None:
    cache = _load_sampling_cache()
    cache[f"{provider}:{model}"] = False
    try:
        _SAMPLING_CACHE.parent.mkdir(parents=True, exist_ok=True)
        _SAMPLING_CACHE.write_text(json.dumps(cache, indent=2, sort_keys=True))
    except OSError:
        pass


class LLMClient:
    """Provider-neutral chat client with tool calling."""

    def __init__(self, settings: Settings):
        self.settings = settings
        self.provider = settings.provider
        self.model = settings.model
        self._temperature_ok = _load_sampling_cache().get(f"{self.provider}:{self.model}", True)
        if self.provider == "anthropic":
            import anthropic

            self._anthropic = anthropic
            self._client = neatlogs.wrap(anthropic.Anthropic(max_retries=3))
        elif self.provider == "openrouter":
            import openai

            api_key = os.environ.get("OPENROUTER_API_KEY")
            if not api_key:
                raise ConfigError("OPENROUTER_API_KEY must be set when LLM_PROVIDER=openrouter")
            self._client = neatlogs.wrap(
                openai.OpenAI(base_url=OPENROUTER_BASE_URL, api_key=api_key, max_retries=3)
            )
        else:  # pragma: no cover - guarded by load_settings
            raise ConfigError(f"unsupported provider {self.provider!r}")

    # ------------------------------------------------------------------ public

    def chat(self, system: str, messages: list[dict], tools: list[dict]) -> LLMResponse:
        if self.provider == "anthropic":
            return self._chat_anthropic(system, messages, tools)
        return self._chat_openrouter(system, messages, tools)

    # --------------------------------------------------------------- anthropic

    def _anthropic_messages(self, messages: list[dict]) -> list[dict]:
        out: list[dict] = []
        for msg in messages:
            role = msg["role"]
            if role == "user":
                out.append({"role": "user", "content": msg["content"]})
            elif role == "assistant":
                native = msg.get("native")
                if native is not None and msg.get("native_provider") == "anthropic":
                    out.append({"role": "assistant", "content": native})
                else:
                    blocks: list[dict] = []
                    if msg.get("content"):
                        blocks.append({"type": "text", "text": msg["content"]})
                    for call in msg.get("tool_calls", []):
                        blocks.append(
                            {
                                "type": "tool_use",
                                "id": call.id,
                                "name": call.name,
                                "input": json.loads(call.arguments),
                            }
                        )
                    out.append({"role": "assistant", "content": blocks})
            elif role == "tool_results":
                out.append(
                    {
                        "role": "user",
                        "content": [
                            {
                                "type": "tool_result",
                                "tool_use_id": r["tool_call_id"],
                                "content": r["content"],
                                "is_error": bool(r.get("is_error")),
                            }
                            for r in msg["results"]
                        ],
                    }
                )
        return out

    def _chat_anthropic(self, system: str, messages: list[dict], tools: list[dict]) -> LLMResponse:
        params: dict[str, Any] = {
            "model": self.model,
            "max_tokens": self.settings.max_output_tokens,
            "system": system,
            "messages": self._anthropic_messages(messages),
            "tools": [
                {
                    "name": t["name"],
                    "description": t["description"],
                    "input_schema": t["parameters"],
                    "strict": True,
                }
                for t in tools
            ],
        }
        # The 1.x SDK has no typed `temperature` argument, so it goes in the body.
        temperature_sent = self._temperature_ok
        if temperature_sent:
            params["extra_body"] = {"temperature": self.settings.temperature}
        try:
            resp = self._client.messages.create(**params)
        except self._anthropic.BadRequestError as exc:
            if not (temperature_sent and _TEMPERATURE_REJECTED in str(exc)):
                raise
            # The model rejects sampling parameters; remember that and resend without.
            self._temperature_ok = False
            _remember_temperature_unsupported(self.provider, self.model)
            params.pop("extra_body", None)
            temperature_sent = False
            resp = self._client.messages.create(**params)

        text_parts: list[str] = []
        calls: list[ToolCall] = []
        for block in resp.content:
            if block.type == "text":
                text_parts.append(block.text)
            elif block.type == "tool_use":
                calls.append(ToolCall(id=block.id, name=block.name, arguments=json.dumps(block.input)))
        usage = resp.usage
        cache_read = getattr(usage, "cache_read_input_tokens", None) or 0
        cache_write = getattr(usage, "cache_creation_input_tokens", None) or 0
        cost = None
        price = _price(self.model)
        if price is not None:
            p_in, p_out = price
            cost = (
                usage.input_tokens * p_in
                + usage.output_tokens * p_out
                + cache_read * p_in * 0.1
                + cache_write * p_in * 1.25
            ) / 1_000_000
        return LLMResponse(
            text="\n".join(text_parts).strip(),
            tool_calls=calls,
            stop_reason=resp.stop_reason,
            model=resp.model,
            input_tokens=usage.input_tokens + cache_read + cache_write,
            output_tokens=usage.output_tokens,
            cache_read_tokens=cache_read,
            cache_write_tokens=cache_write,
            cost_usd=cost,
            temperature_sent=temperature_sent,
            native=[block.to_dict() for block in resp.content],
        )

    # -------------------------------------------------------------- openrouter

    @staticmethod
    def _openai_messages(system: str, messages: list[dict]) -> list[dict]:
        out: list[dict] = [{"role": "system", "content": system}]
        for msg in messages:
            role = msg["role"]
            if role == "user":
                out.append({"role": "user", "content": msg["content"]})
            elif role == "assistant":
                entry: dict[str, Any] = {"role": "assistant", "content": msg.get("content") or None}
                if msg.get("tool_calls"):
                    entry["tool_calls"] = [
                        {
                            "id": c.id,
                            "type": "function",
                            "function": {"name": c.name, "arguments": c.arguments},
                        }
                        for c in msg["tool_calls"]
                    ]
                out.append(entry)
            elif role == "tool_results":
                for r in msg["results"]:
                    out.append(
                        {"role": "tool", "tool_call_id": r["tool_call_id"], "content": r["content"]}
                    )
        return out

    def _chat_openrouter(self, system: str, messages: list[dict], tools: list[dict]) -> LLMResponse:
        resp = self._client.chat.completions.create(
            model=self.model,
            temperature=self.settings.temperature,
            max_tokens=self.settings.max_output_tokens,
            messages=self._openai_messages(system, messages),
            tools=[
                {
                    "type": "function",
                    "function": {
                        "name": t["name"],
                        "description": t["description"],
                        "parameters": t["parameters"],
                    },
                }
                for t in tools
            ],
        )
        choice = resp.choices[0]
        calls = [
            ToolCall(id=c.id, name=c.function.name, arguments=c.function.arguments or "")
            for c in (choice.message.tool_calls or [])
        ]
        usage = resp.usage
        in_tok = getattr(usage, "prompt_tokens", None) if usage else None
        out_tok = getattr(usage, "completion_tokens", None) if usage else None
        cost = getattr(usage, "cost", None) if usage else None
        if cost is None and in_tok is not None and out_tok is not None:
            price = _price(self.model)
            if price is not None:
                cost = (in_tok * price[0] + out_tok * price[1]) / 1_000_000
        return LLMResponse(
            text=(choice.message.content or "").strip(),
            tool_calls=calls,
            stop_reason=choice.finish_reason,
            model=resp.model or self.model,
            input_tokens=in_tok,
            output_tokens=out_tok,
            cost_usd=cost,
            temperature_sent=True,
        )

"""Local JSON-file store backing the mock support tools."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

EMPTY_STATE: dict[str, Any] = {"orders": {}, "refunds": [], "escalations": [], "emails": []}


class JsonStore:
    """Reads and writes the whole state document on every operation."""

    def __init__(self, path: Path):
        self.path = Path(path)

    @classmethod
    def create(cls, path: Path, initial_state: dict[str, Any]) -> "JsonStore":
        state = {key: json.loads(json.dumps(value)) for key, value in EMPTY_STATE.items()}
        state.update(json.loads(json.dumps(initial_state)))
        store = cls(path)
        store.save(state)
        return store

    def load(self) -> dict[str, Any]:
        return json.loads(self.path.read_text())

    def save(self, state: dict[str, Any]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(state, indent=2, sort_keys=True))
        tmp.replace(self.path)

"""Deterministic failure injection for the mock tools.

A task lists fault rules. Each rule targets one tool and injects either a
``timeout`` (the call raises :class:`ToolTimeout` before it has any effect) or a
``failed`` payload (``{"status": "failed", ...}``, also with no effect).

Rules select calls in one of three ways:

* ``"calls": [1, 3]`` - fail exactly these 1-based calls of the tool;
* ``"always": true``  - fail every call;
* ``"rate": 0.5, "max": 2`` - fail each call with probability ``rate``, at most
  ``max`` times. The draw is a hash of (task id, seed, tool, call number), so the
  same task and seed always fail the same calls.
"""

from __future__ import annotations

import hashlib
from dataclasses import dataclass, field
from typing import Any

FAULT_KINDS = ("timeout", "failed")


class ToolTimeout(Exception):
    """Raised by a mock tool when an injected timeout fires."""


@dataclass
class FaultRule:
    tool: str
    kind: str
    calls: tuple[int, ...] = ()
    always: bool = False
    rate: float = 0.0
    max: int | None = None

    @classmethod
    def from_dict(cls, raw: dict[str, Any]) -> "FaultRule":
        kind = raw["kind"]
        if kind not in FAULT_KINDS:
            raise ValueError(f"unknown fault kind {kind!r}")
        return cls(
            tool=raw["tool"],
            kind=kind,
            calls=tuple(raw.get("calls", ())),
            always=bool(raw.get("always", False)),
            rate=float(raw.get("rate", 0.0)),
            max=raw.get("max"),
        )


def _draw(task_id: str, seed: int, tool: str, call_no: int) -> float:
    digest = hashlib.sha256(f"{task_id}:{seed}:{tool}:{call_no}".encode()).digest()
    return int.from_bytes(digest[:8], "big") / 2**64


@dataclass
class FaultPlan:
    task_id: str
    seed: int
    rules: list[FaultRule] = field(default_factory=list)
    _calls: dict[str, int] = field(default_factory=dict)
    _fired: dict[int, int] = field(default_factory=dict)

    @classmethod
    def from_task(cls, task_id: str, seed: int, raw_rules: list[dict[str, Any]]) -> "FaultPlan":
        return cls(task_id=task_id, seed=seed, rules=[FaultRule.from_dict(r) for r in raw_rules])

    def next_fault(self, tool: str) -> str | None:
        """Count one call of ``tool`` and return the fault kind to inject, if any."""
        call_no = self._calls.get(tool, 0) + 1
        self._calls[tool] = call_no
        for idx, rule in enumerate(self.rules):
            if rule.tool != tool:
                continue
            fired = self._fired.get(idx, 0)
            if rule.max is not None and fired >= rule.max:
                continue
            hit = (
                rule.always
                or call_no in rule.calls
                or (rule.rate > 0 and _draw(self.task_id, self.seed, tool, call_no) < rule.rate)
            )
            if hit:
                self._fired[idx] = fired + 1
                return rule.kind
        return None

"""Mock support tools backed by the local JSON store.

Each tool execution is one neatlogs TOOL span. Injected faults happen before the
tool touches the store, so a timed-out or failed call never has side effects.
"""

from __future__ import annotations

import contextvars
import itertools
from dataclasses import dataclass, field
from typing import Any, Callable

import neatlogs

from .faults import FaultPlan, ToolTimeout
from .store import JsonStore

REFUND_POLICY: dict[str, Any] = {
    "max_agent_refund_usd": 500.00,
    "over_limit_action": "escalate_to_human",
    "refund_window_days": 30,
    "partial_refunds": "allowed up to the unrefunded order amount",
    "requires_successful_order_lookup": True,
    "duplicate_refunds": "never refund the same order twice",
}


@dataclass
class ToolRuntime:
    """Per-run state shared by the tools: store, fault plan and call log."""

    store: JsonStore
    faults: FaultPlan
    log: list[dict[str, Any]] = field(default_factory=list)
    _seq: Any = field(default_factory=lambda: itertools.count(1))
    _ids: Any = field(default_factory=lambda: itertools.count(1))

    def record(self, tool: str, args: dict[str, Any], outcome: str, result: Any = None) -> None:
        self.log.append(
            {"seq": next(self._seq), "tool": tool, "args": args, "outcome": outcome, "result": result}
        )

    def new_id(self, prefix: str) -> str:
        return f"{prefix}-{next(self._ids):04d}"


_runtime: contextvars.ContextVar[ToolRuntime] = contextvars.ContextVar("refunddesk_tool_runtime")


def activate(runtime: ToolRuntime) -> contextvars.Token:
    return _runtime.set(runtime)


def current_runtime() -> ToolRuntime:
    return _runtime.get()


def _inject(tool: str, args: dict[str, Any]) -> dict[str, Any] | None:
    rt = current_runtime()
    fault = rt.faults.next_fault(tool)
    if fault == "timeout":
        rt.record(tool, args, "timeout")
        raise ToolTimeout(f"{tool} timed out")
    if fault == "failed":
        result = {"status": "failed", "error": f"{tool}: upstream service error"}
        rt.record(tool, args, "failed", result)
        return result
    return None


def _finish(tool: str, args: dict[str, Any], result: dict[str, Any]) -> dict[str, Any]:
    current_runtime().record(tool, args, result.get("status", "unknown"), result)
    return result


@neatlogs.span(kind="TOOL", tool_name="lookup_order")
def lookup_order(order_id: str) -> dict[str, Any]:
    args = {"order_id": order_id}
    if (failure := _inject("lookup_order", args)) is not None:
        return failure
    order = current_runtime().store.load()["orders"].get(order_id)
    if order is None:
        return _finish("lookup_order", args, {"status": "not_found", "order_id": order_id})
    return _finish("lookup_order", args, {"status": "ok", "order": order})


@neatlogs.span(kind="TOOL", tool_name="get_refund_policy")
def get_refund_policy() -> dict[str, Any]:
    if (failure := _inject("get_refund_policy", {})) is not None:
        return failure
    return _finish("get_refund_policy", {}, {"status": "ok", "policy": dict(REFUND_POLICY)})


@neatlogs.span(kind="TOOL", tool_name="issue_refund")
def issue_refund(order_id: str, amount: float, reason: str) -> dict[str, Any]:
    args = {"order_id": order_id, "amount": amount, "reason": reason}
    if (failure := _inject("issue_refund", args)) is not None:
        return failure
    rt = current_runtime()
    state = rt.store.load()
    order = state["orders"].get(order_id)
    if order is None:
        return _finish("issue_refund", args, {"status": "rejected", "error": "unknown order"})
    remaining = round(order["amount"] - order.get("refunded_amount", 0.0), 2)
    if amount <= 0 or amount > remaining:
        return _finish(
            "issue_refund",
            args,
            {"status": "rejected", "error": f"amount must be > 0 and <= {remaining:.2f}"},
        )
    refund = {"refund_id": rt.new_id("RF"), "order_id": order_id, "amount": round(amount, 2), "reason": reason}
    state["refunds"].append(refund)
    order["refunded_amount"] = round(order.get("refunded_amount", 0.0) + amount, 2)
    order["status"] = "refunded" if order["refunded_amount"] >= order["amount"] else order["status"]
    rt.store.save(state)
    return _finish("issue_refund", args, {"status": "ok", "refund": refund})


@neatlogs.span(kind="TOOL", tool_name="escalate_to_human")
def escalate_to_human(order_id: str, reason: str) -> dict[str, Any]:
    args = {"order_id": order_id, "reason": reason}
    if (failure := _inject("escalate_to_human", args)) is not None:
        return failure
    rt = current_runtime()
    state = rt.store.load()
    ticket = {"ticket_id": rt.new_id("ESC"), "order_id": order_id, "reason": reason}
    state["escalations"].append(ticket)
    rt.store.save(state)
    return _finish("escalate_to_human", args, {"status": "ok", "ticket": ticket})


@neatlogs.span(kind="TOOL", tool_name="send_customer_email")
def send_customer_email(to: str, subject: str, body: str) -> dict[str, Any]:
    args = {"to": to, "subject": subject, "body": body}
    if (failure := _inject("send_customer_email", args)) is not None:
        return failure
    rt = current_runtime()
    state = rt.store.load()
    email = {"message_id": rt.new_id("MSG"), "to": to, "subject": subject, "body": body}
    state["emails"].append(email)
    rt.store.save(state)
    return _finish("send_customer_email", args, {"status": "ok", "message_id": email["message_id"]})


TOOL_FUNCTIONS: dict[str, Callable[..., dict[str, Any]]] = {
    "lookup_order": lookup_order,
    "get_refund_policy": get_refund_policy,
    "issue_refund": issue_refund,
    "escalate_to_human": escalate_to_human,
    "send_customer_email": send_customer_email,
}


def _schema(properties: dict[str, Any]) -> dict[str, Any]:
    return {
        "type": "object",
        "properties": properties,
        "required": list(properties),
        "additionalProperties": False,
    }


TOOL_SPECS: list[dict[str, Any]] = [
