"""Behaviour-neutral maintenance edits for the history branches.

Usage: python hist_edits.py <repo> <edit-name>   -> applies one edit, prints the commit message.
"""
import re
import sys
from pathlib import Path

ROOT = Path(sys.argv[1])


def rd(p):
    return (ROOT / p).read_text()


def wr(p, s):
    (ROOT / p).parent.mkdir(parents=True, exist_ok=True)
    (ROOT / p).write_text(s)


def rep(p, old, new, count=1):
    s = rd(p)
    n = s.count(old)
    if n != count:
        raise SystemExit(f"{p}: expected {count} match(es) for {old!r}, found {n}")
    wr(p, s.replace(old, new))


def append(p, text):
    s = rd(p) if (ROOT / p).exists() else ""
    if not s.endswith("\n") and s:
        s += "\n"
    wr(p, s + text)


def rename(paths, old, new):
    total = 0
    for p in paths:
        s = rd(p)
        c = len(re.findall(rf"\b{re.escape(old)}\b", s))
        total += c
        wr(p, re.sub(rf"\b{re.escape(old)}\b", new, s))
    if total == 0:
        raise SystemExit(f"rename {old}: no occurrences")


EDITS = {}


def edit(name, msg):
    def deco(fn):
        EDITS[name] = (msg, fn)
        return fn
    return deco


